-- Metadata vectors: 1536-dim Narrative_DNA per title (R2.6, R17.6).
ON CONFLICT (metadata_id) DO NOTHING;

-- Financial projections, stamped with the active model version (R8.6, R25.3, R26.2).
ON CONFLICT (projection_id) DO NOTHING;

-- License terms per title (R22). The deal-term columns (windowing_rules,
-- holdbacks, milestone_schedule) are encrypted-at-rest TEXT (R28.1); the
-- seed loads plaintext JSON for the local/dev passthrough.
ON CONFLICT (license_id) DO NOTHING;

-- Subscriber cluster preference vectors (1536-dim) for the Vector_Search_Engine (design R3).
ON CONFLICT (cluster_id) DO NOTHING;
